#include <bits/stdc++.h>
using namespace std;
#define ll long long
void solve(){
    int n; cin >> n;
    vector<ll> v(3*n);
    for(int i=0; i<3*n; i++){
        cin >> v[i];
    }
    
    sort(v.begin(), v.end(), greater<ll>());
    
    vector<ll> pref(3*n+1);
    for(int i=1; i<=3*n; i++){
        pref[i] = pref[i-1] + v[i-1];
    }
    ll ans = pref[n]*6;
    for(int a=0; a<n; a++){
        ll temp = 6*(pref[a]);
        ll left = 1, right = n-a+1;
        while(left<right){
            ll mid = (left+right)/2;
            ll x = v[a+2*mid-1] + v[a+2*mid-2];
            ll y = v[3*n-(2*a+mid)];
            if(x>3*y){
                left = mid+1;
            }
            else{
                right=mid;
            }
        }
        
        ll b = left-1;
        // if(b==-1) b = 0;
        // cout << "chosen: " << a << ' ' << b << endl;
        ll temp2 = pref[a+2*b]-pref[a];
        temp2*=4;
        ll c = n-a-b;
        ll temp3 = pref[a+2*b+3*c] - pref[a+2*b];
        temp3*=3;
        ans = max(ans, temp + temp2 + temp3);
    }
    
    cout << ans << endl;
}

int main() {
	// your code goes here
    int t; cin >> t;
    while(t--){
        solve();
    }
}
